reference_solution:
def minimum_fibonacci_count(k):
 numbers=[1,2]
 while numbers[-1]<k:numbers.append(numbers[-1]+numbers[-2])
 answer=0
 for value in reversed(numbers):
  if value<=k:k-=value;answer+=1
 return answer

